'use strict';

// MODULES //

import resolveLayout from '@stdlib/blas-base-layout-resolve-str';
import isColumnMajor from '@stdlib/ndarray-base-assert-is-column-major-string';
import stride2offset from '@stdlib/strided-base-stride2offset';
import max from '@stdlib/math-base-special-fast-max';
import format from '@stdlib/error-tools-fmtprodmsg';
import ndarray from './ndarray.js';


// MAIN //

/**
* Computes the Cartesian product for two double-precision complex floating-point strided arrays.
*
* ## Notes
*
* -   Pairs are stored as rows in the output matrix, where the first column contains the first element of each pair and the second column contains the second element.
*
* @param {(integer|string)} order - storage layout
* @param {NonNegativeInteger} M - number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of indexed elements in `y`
* @param {Complex128Array} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {Complex128Array} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {Complex128Array} out - output array
* @param {integer} LDO - stride length between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of `out`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} ninth argument must be a valid stride length
* @returns {Complex128Array} output array
*
* @example
* import Complex128Array from '@stdlib/array-complex128';
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Complex128Array( [ 5.0, 6.0, 7.0, 8.0 ] );
* var out = new Complex128Array( 8 );
*
* zcartesianProduct( 'row-major', x.length, y.length, x, 1, y, 1, out, 2 );
* // out => <Complex128Array>[ 1.0, 2.0, 5.0, 6.0, 1.0, 2.0, 7.0, 8.0, 3.0, 4.0, 5.0, 6.0, 3.0, 4.0, 7.0, 8.0 ]
*/
function zcartesianProduct( order, M, N, x, strideX, y, strideY, out, LDO ) {
	var sa1;
	var sa2;
	var ox;
	var oy;
	var l;

	l = resolveLayout( order );
	if ( l === null ) {
		throw new TypeError( format( '34rFx', order ) );
	}
	if ( isColumnMajor( l ) ) {
		if ( LDO < max( 1, M*N ) ) {
			throw new RangeError( format( '34rGi', M*N, LDO ) );
		}
		sa1 = 1;
		sa2 = LDO;
	} else { // order === 'row-major'
		if ( LDO < 2 ) {
			throw new RangeError( format( '34rGi', 2, LDO ) );
		}
		sa1 = LDO;
		sa2 = 1;
	}
	ox = stride2offset( M, strideX );
	oy = stride2offset( N, strideY );
	return ndarray( M, N, x, strideX, ox, y, strideY, oy, out, sa1, sa2, 0 );
}


// EXPORTS //

export default zcartesianProduct;
